python3.checker:
from typing import Any, List

class Checker:
    def partition(self, s: str, result: Any) -> bool:
        if not isinstance(result, list):
            return False

        expected = set()

        def build(idx: int, path: List[str]) -> None:
            if idx == len(s):
                expected.add(tuple(path))
                return
            for end in range(idx + 1, len(s) + 1):
                piece = s[idx:end]
                if piece == piece[::-1]:
                    path.append(piece)
                    build(end, path)
                    path.pop()

        build(0, [])

        seen = set()
        for partition in result:
            if not isinstance(partition, list):
                return False
            if tuple(partition) in seen:
                return False
            seen.add(tuple(partition))
            if "".join(partition) != s:
                return False
            for piece in partition:
                if not isinstance(piece, str):
                    return False
                if piece == "" or piece != piece[::-1]:
                    return False

        return seen == expected

